-- The master list from PDPL's ERP (the user, 23 Nov 2026): two sheets, "GLP1 InRange" (23 items) and "InRange GLP1
-- Supporting" (107 items: for nausea, constipation, acidity, loose motions, rehydration and gut flora). Each item
-- carries the ERP's Product ID as its sku, so a later price list or the ERP link can find it.
-- Prices: the 14 pens already on the list keep theirs. Everything new has none yet, so a doctor can prescribe it
-- (it prints on the prescription) but it is not sold or billed until a price is added (mrp_paise).
-- Read from the sheets: the brand and strength from the product name (two rows' composition cells disagree with
-- their names: Mounjaro 5 mg KwikPen says 7.5 mg, Wegovy 1 mg says 4 mg; the name is used). A bottle, powder or
-- sachet has its size as the strength, so "Duphalac 250 mL" and "Duphalac 450 mL" are told apart.
-- Run again safely: an item is matched on its sku.

-- the pens already on the list take their Product IDs
update public.medicines m set sku = v.sku
from (values
  ('Mounjaro KwikPen', '10 mg', '57403'),
  ('Mounjaro KwikPen', '12.5 mg', '60258'),
  ('Mounjaro KwikPen', '15 mg', '60513'),
  ('Mounjaro KwikPen', '2.5 mg', '57374'),
  ('Mounjaro KwikPen', '5 mg', '57379'),
  ('Mounjaro KwikPen', '7.5 mg', '57401'),
  ('Ozempic', '0.25 mg', '62920'),
  ('Ozempic', '0.5 mg', '71969'),
  ('Ozempic', '1 mg', '61892'),
  ('Wegovy FlexTouch', '0.25 mg', '57697'),
  ('Wegovy FlexTouch', '0.5 mg', '58410'),
  ('Wegovy FlexTouch', '1 mg', '57600'),
  ('Wegovy FlexTouch', '1.7 mg', '60613'),
  ('Wegovy FlexTouch', '2.4 mg', '60612')
) as v(brand, strength, sku)
where m.sku is null and m.brand = v.brand and m.strength = v.strength;

on conflict (sku) do update set
  brand = excluded.brand, molecule = excluded.molecule, form = excluded.form, strength = excluded.strength,
  -- an item that is priced keeps its pack as it is sold
  pack = case when public.medicines.mrp_paise is null then excluded.pack else public.medicines.pack end,
  pack_days = case when public.medicines.mrp_paise is null then excluded.pack_days else public.medicines.pack_days end,
  route = excluded.route, kind = excluded.kind, active = true;
